import{initializeApp}from'https://www.gstatic.com/firebasejs/12.18.0/firebase-app.js';
import{getAuth,onAuthStateChanged,signInWithEmailAndPassword,signOut,sendPasswordResetEmail,setPersistence,browserLocalPersistence}from'https://www.gstatic.com/firebasejs/12.18.0/firebase-auth.js';
import{getFirestore,doc,getDoc,collection,query,where,getDocs,orderBy,limit,writeBatch,setDoc,updateDoc,serverTimestamp,deleteDoc}from'https://www.gstatic.com/firebasejs/12.18.0/firebase-firestore.js';
const $=id=>document.getElementById(id),cfg=window.WILDENHORST_FIREBASE||{};let auth,db,user,profile,season;
const APP_VERSION='0.6';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function show(id){$(id)?.classList.remove('hidden')}function hide(id){$(id)?.classList.add('hidden')}
function admin(){return profile?.role==='admin'||profile?.role==='headAdmin'}function head(){return profile?.role==='headAdmin'}
function keyDate(k){if(!k)return new Date(0);const[y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d,12)}
function dateText(k,year=true){if(!k)return'';return new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long',...(year?{year:'numeric'}:{})}).format(keyDate(k))}
function toKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function timeText(v){return String(v||'18:00').slice(0,5)}
function closeOffset(day){return day==='wednesday'?3:day==='thursday'?2:day==='saturday'?0:1}
function closeAtWith(dateKey,day='friday',time='18:00'){const d=keyDate(dateKey);d.setDate(d.getDate()-closeOffset(day));const[h,m]=timeText(time).split(':').map(Number);d.setHours(h,m,0,0);return d}
function closeDayNl(day){return day==='wednesday'?'woensdag':day==='thursday'?'donderdag':day==='saturday'?'zaterdag':'vrijdag'}
function seasonId(){return season?.id||'2026-2027'}
if(!cfg.configured){show('setup')}else{const app=initializeApp(cfg);auth=getAuth(app);db=getFirestore(app);setPersistence(auth,browserLocalPersistence);onAuthStateChanged(auth,authChanged)}
async function authChanged(u){if(!u){user=profile=season=null;hide('main');hide('setup');show('login');return}user=u;const s=await getDoc(doc(db,'users',u.uid));if(!s.exists()||s.data().status!=='active'){await signOut(auth);return}profile={id:s.id,...s.data()};const qs=await getDocs(query(collection(db,'seasons'),where('active','==',true),limit(1)));season=qs.empty?null:{id:qs.docs[0].id,...qs.docs[0].data()};hide('login');show('main');go('home')}
$('loginForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await signInWithEmailAndPassword(auth,$('email').value.trim(),$('password').value)}catch(_){const m=$('loginMessage');m.textContent='Inloggen is niet gelukt. Controleer e-mailadres en wachtwoord.';m.className='message error';show('loginMessage')}});
$('forgotPassword')?.addEventListener('click',async()=>{const e=$('email').value.trim(),m=$('loginMessage');if(!e){m.textContent='Vul eerst je e-mailadres in.';m.className='message error';show('loginMessage');return}try{await sendPasswordResetEmail(auth,e);m.textContent='Er is een resetmail verstuurd.';m.className='message';show('loginMessage')}catch(_){m.textContent='De resetmail kon niet worden verstuurd.';m.className='message error';show('loginMessage')}});
$('forgotLogin')?.addEventListener('click',()=>$('forgotLoginDialog').showModal());document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));
function nav(r){document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===r))}function go(r){nav(r);if(r==='home')home();if(r==='couple')couple();if(r==='saturday')saturday();if(r==='standings')standings();if(r==='more')more()}
async function playDates(){if(!season)return[];const s=await getDocs(query(collection(db,'seasons',season.id,'playDates'),orderBy('dateKey')));return s.docs.map(d=>({id:d.id,...d.data()})).filter(d=>d.status!=='cancelled')}
function endMoment(d){const x=keyDate(d.dateKey);const[h,m]=(d.endTime||season?.endTime||'12:00').split(':').map(Number);x.setHours(h,m,0,0);return x}
function nextPlayDate(ds,now=new Date()){return ds.find(d=>endMoment(d)>=now)||null}
function previousPlayDate(ds,now=new Date()){return [...ds].reverse().find(d=>endMoment(d)<now)||null}
async function home(){
 const n=profile?.firstName||profile?.displayName||profile?.name||'';$('screen').innerHTML='<div class="card"><h2>Home</h2><p>Laden…</p></div>';
 const ds=await playDates(),now=new Date(),next=nextPlayDate(ds,now),prev=previousPlayDate(ds,now);let nextHtml='<div class="card"><b>Er is nog geen volgende speeldag ingesteld.</b></div>';
 if(next){
  const [plans,couples]=await Promise.all([getDocs(collection(db,'seasons',season.id,'playDates',next.id,'couplePlans')),getDocs(collection(db,'seasons',season.id,'couples'))]);
  const total=couples.docs.filter(x=>x.data().status!=='inactive').length,valid=plans.docs.filter(x=>validPair(x.data().member1Status,x.data().member2Status)),playing=valid.filter(x=>x.data().member1Status==='speelt'||x.data().member2Status==='speelt').length,need=valid.filter(x=>x.data().member1Status==='afwezig'&&x.data().member2Status==='afwezig').length;
  const own=profile?.coupleId?plans.docs.find(x=>x.id===profile.coupleId)?.data():null;let ownText='Nog niet ingevuld';if(own){const mineId=profile.playerId||profile.id;ownText=own.member1Id===mineId?statusLabel(own.member1Status):own.member2Id===mineId?statusLabel(own.member2Status):(own.member1Status==='speelt'||own.member2Status==='speelt'?'Koppel ingevuld':'Beide afwezig')}
  const close=next.closeAt?.toDate?next.closeAt.toDate():closeAtWith(next.dateKey,season?.defaultCloseDay,season?.defaultCloseTime);
  nextHtml=`<section class="hero next-hero"><div class="eyebrow">🎾 Volgende speeldag</div><h1>${esc(dateText(next.dateKey))}</h1><p><b>${esc(next.startTime||season?.startTime||'10:00')}–${esc(next.endTime||season?.endTime||'12:00')}</b> · ${Number(next.courtCount||season?.defaultCourts||2)} banen</p><div class="deadline"><b>Planning wijzigen tot</b><br>⏰ ${esc(dateText(toKey(close),false))} ${esc(timeText(`${String(close.getHours()).padStart(2,'0')}:${String(close.getMinutes()).padStart(2,'0')}`))}</div><div class="home-stats"><div><b>${playing}</b><span>spelers gepland</span></div><div><b>${valid.length}/${total}</b><span>koppels ingevuld</span></div><div><b>${Math.max(0,total-valid.length)}</b><span>nog invullen</span></div></div>${need?`<div class="message error">⚠️ ${need} ${need===1?'koppel heeft':'koppels hebben'} een vervanger nodig.</div>`:''}<div class="my-status"><b>Jouw planning:</b> ${esc(ownText)}</div></section>`;
 }
 let lastHtml='<div class="card"><h3>🏆 Laatste uitslag</h3><p>Nog geen gespeelde zaterdag met uitslagen.</p></div>';
 if(prev){const rs=await getDocs(collection(db,'seasons',season.id,'playDates',prev.id,'results'));if(!rs.empty){lastHtml=`<div class="card"><h3>🏆 Laatste uitslag · ${esc(dateText(prev.dateKey,false))}</h3>${rs.docs.slice(0,4).map(x=>resultLine(x.data())).join('')}<button class="link" data-go="standings">Bekijk stand →</button></div>`}else{lastHtml=`<div class="card"><h3>🏆 Laatste speelzaterdag · ${esc(dateText(prev.dateKey,false))}</h3><p>Er zijn nog geen uitslagen ingevoerd.</p></div>`}}
 $('screen').innerHTML=`<section class="welcome"><h2>Welkom${n?', '+esc(n):''}</h2><span>${esc(season?.name||'Actief seizoen')}</span></section>${nextHtml}${lastHtml}${admin()?'<div class="adminbar"><b>⚙️ Beheerder</b><button id="beheer">Open beheer</button></div>':''}<div class="tiles"><button class="tile" data-go="couple">👥<strong>Mijn koppel</strong><small>Wie speelt, reserve of afwezig is.</small></button><button class="tile" data-go="saturday">🎾<strong>Zaterdag</strong><small>Baanindeling en uitslagen.</small></button><button class="tile" data-go="standings">🏆<strong>Stand</strong><small>Punten per koppel.</small></button><button class="tile" data-go="more">ℹ️<strong>Uitleg & gegevens</strong><small>Spelregels en eigen gegevens.</small></button></div>`;
 $('screen').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('beheer')?.addEventListener('click',beheer)
}
function resultLine(r){const a=r.coupleAName||r.teamA||'Koppel A',b=r.coupleBName||r.teamB||'Koppel B',score=r.scoreText||r.score||'';return `<div class="result-line"><b>${esc(a)}</b><span>${esc(score||'–')}</span><b>${esc(b)}</b></div>`}
function statusLabel(s){return s==='speelt'?'Speelt':s==='reserve'?'Reserve':s==='afwezig'?'Afwezig':'Nog kiezen'}
function validPair(a,b){return (a==='speelt'&&(b==='reserve'||b==='afwezig'))||(b==='speelt'&&(a==='reserve'||a==='afwezig'))||(a==='afwezig'&&b==='afwezig')}
function planHint(a,b,n1,n2){if(a==='afwezig'&&b==='afwezig')return '⚠️ Beide afwezig — vervanger nodig.';if(a==='speelt')return `✓ ${esc(n1)} speelt${b==='afwezig'?'; '+esc(n2)+' is afwezig':'; '+esc(n2)+' is reserve'}.`;if(b==='speelt')return `✓ ${esc(n2)} speelt${a==='afwezig'?'; '+esc(n1)+' is afwezig':'; '+esc(n1)+' is reserve'}.`;return 'Kies wie speelt. De partner wordt automatisch Reserve.'}
async function couple(){
 $('screen').innerHTML='<div class="card"><h2>Mijn koppel</h2><p>Laden…</p></div>';if(!profile?.coupleId){$('screen').innerHTML='<div class="card"><h2>Mijn koppel</h2><p>Nog geen koppel gekoppeld.</p></div>';return}
 const [c,dates]=await Promise.all([getDoc(doc(db,'seasons',season.id,'couples',profile.coupleId)),playDates()]);const cp=c.exists()?c.data():{},ids=Array.isArray(cp.memberIds)?cp.memberIds:[],nameParts=String(cp.name||'').split(' – '),names=[nameParts[0]||'Speler 1',nameParts[1]||'Speler 2'];const planSnaps=await Promise.all(dates.map(d=>getDoc(doc(db,'seasons',season.id,'playDates',d.id,'couplePlans',profile.coupleId))));
 let html=`<div class="card"><h2>${esc(cp.name||'Mijn koppel')}</h2><p><b>Zo werkt het:</b> tik per zaterdag op <b>Speelt</b> bij degene die speelt. De partner wordt automatisch <b>Reserve</b>. Is iemand niet beschikbaar, kies <b>Afwezig</b>.</p><div id="coupleSummary"></div><div id="coupleStats" class="player-stats"></div></div>`;
 dates.forEach((d,i)=>{const x=planSnaps[i].exists()?planSnaps[i].data():{},a=x.member1Status||'',b=x.member2Status||'',close=d.closeAt?.toDate?d.closeAt.toDate():closeAtWith(d.dateKey,season?.defaultCloseDay,season?.defaultCloseTime),locked=!admin()&&new Date()>=close;html+=`<div class="date-card plan-card" data-date="${esc(d.id)}" data-key="${esc(d.dateKey)}" data-id1="${esc(ids[0]||'')}" data-id2="${esc(ids[1]||'')}" data-s1="${esc(a)}" data-s2="${esc(b)}" data-saved1="${esc(a)}" data-saved2="${esc(b)}"><div class="date-head"><b>${esc(dateText(d.dateKey))}</b><span class="status ${locked?'closed':''}">${locked?'Gesloten':'Open'}</span></div><div class="planner-person"><strong>${esc(names[0])}</strong><div class="choice-row" data-who="1"><button type="button" data-status="speelt" ${locked?'disabled':''}>Speelt</button><button type="button" data-status="reserve" ${locked?'disabled':''}>Reserve</button><button type="button" data-status="afwezig" ${locked?'disabled':''}>Afwezig</button></div></div><div class="planner-person"><strong>${esc(names[1])}</strong><div class="choice-row" data-who="2"><button type="button" data-status="speelt" ${locked?'disabled':''}>Speelt</button><button type="button" data-status="reserve" ${locked?'disabled':''}>Reserve</button><button type="button" data-status="afwezig" ${locked?'disabled':''}>Afwezig</button></div></div><div class="plan-hint"></div>${locked?'':`<button type="button" class="save-plan secondary" disabled>Keuze opslaan</button>`}<div class="plan-msg"></div></div>`});
 $('screen').innerHTML=html;document.querySelectorAll('.plan-card').forEach(card=>{paintPlan(card,names);card.querySelectorAll('.choice-row button').forEach(btn=>btn.onclick=()=>choosePlan(card,btn,names));card.querySelector('.save-plan')?.addEventListener('click',()=>savePlan(card,names))});refreshCoupleSummary(names)
}
function refreshCoupleSummary(names){const cards=[...document.querySelectorAll('.plan-card')],now=new Date(),today=toKey(now);const filled=cards.filter(c=>validPair(c.dataset.saved1,c.dataset.saved2)).length;const count=(who,past)=>cards.filter(c=>{const s=who===1?c.dataset.saved1:c.dataset.saved2,isPast=c.dataset.key<today;return s==='speelt'&&(past?isPast:!isPast)}).length;$('coupleSummary').innerHTML=`<div class="message"><b>${filled} van ${cards.length}</b> speelzaterdagen ingevuld. Wijzigen kan tot ${esc(closeDayNl(season?.defaultCloseDay))} ${esc(timeText(season?.defaultCloseTime))}; daarna alleen de beheerder.</div>`;$('coupleStats').innerHTML=`<div><strong>${esc(names[0])}</strong><span>Gepland <b>${count(1,false)}</b></span><span>Gespeeld <b>${count(1,true)}</b></span></div><div><strong>${esc(names[1])}</strong><span>Gepland <b>${count(2,false)}</b></span><span>Gespeeld <b>${count(2,true)}</b></span></div>`}
function choosePlan(card,btn,names){const who=btn.closest('.choice-row').dataset.who,status=btn.dataset.status;let a=card.dataset.s1||'',b=card.dataset.s2||'';if(who==='1')a=status;else b=status;if(status==='speelt'){if(who==='1'&&b!=='afwezig')b='reserve';if(who==='2'&&a!=='afwezig')a='reserve'}if(status==='reserve'){if(who==='1')b='speelt';else a='speelt'}if(status==='afwezig'){if(who==='1'&&b==='reserve')b='speelt';if(who==='2'&&a==='reserve')a='speelt'}card.dataset.s1=a;card.dataset.s2=b;paintPlan(card,names);const save=card.querySelector('.save-plan');if(save)save.disabled=!validPair(a,b)}
function paintPlan(card,names){const a=card.dataset.s1||'',b=card.dataset.s2||'';card.querySelectorAll('.choice-row').forEach(row=>{const s=row.dataset.who==='1'?a:b;row.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x.dataset.status===s))});const h=card.querySelector('.plan-hint');if(h)h.innerHTML=planHint(a,b,names[0],names[1])}
async function savePlan(card,names){const a=card.dataset.s1||'',b=card.dataset.s2||'',btn=card.querySelector('.save-plan'),msg=card.querySelector('.plan-msg');if(!validPair(a,b)){msg.textContent='Kies een geldige combinatie.';msg.className='plan-msg error';return}btn.disabled=true;btn.textContent='Opslaan…';msg.textContent='';try{await setDoc(doc(db,'seasons',season.id,'playDates',card.dataset.date,'couplePlans',profile.coupleId),{coupleId:profile.coupleId,member1Id:card.dataset.id1,member1Status:a,member2Id:card.dataset.id2,member2Status:b,updatedBy:user.uid,updatedAt:serverTimestamp()},{merge:false});card.dataset.saved1=a;card.dataset.saved2=b;msg.textContent='✓ Opgeslagen';msg.className='plan-msg ok';refreshCoupleSummary(names);btn.textContent='Opgeslagen';setTimeout(()=>{btn.textContent='Keuze opslaan';btn.disabled=true},900)}catch(e){console.error(e);msg.textContent='Opslaan lukt niet. Controleer de Firestore-regels en de deadline.';msg.className='plan-msg error';btn.textContent='Keuze opslaan';btn.disabled=false}}
async function saturday(){
 $('screen').innerHTML='<div class="card"><h2>Zaterdag</h2><p>Laden…</p></div>';const ds=await playDates();if(!ds.length){$('screen').innerHTML='<div class="card">Nog geen speelzaterdag ingesteld.</div>';return}const now=new Date(),next=nextPlayDate(ds,now)||ds.at(-1);$('screen').innerHTML=`<div class="card"><label>Speeldag</label><select id="satDate">${ds.map(d=>`<option value="${esc(d.id)}" ${d.id===next.id?'selected':''}>${esc(dateText(d.dateKey))}</option>`).join('')}</select></div><div id="satBody"></div>`;$('satDate').onchange=()=>renderSaturday(ds.find(d=>d.id===$('satDate').value));renderSaturday(next)
}
async function renderSaturday(d){const host=$('satBody');host.innerHTML='<div class="card">Laden…</div>';const [ls,rs]=await Promise.all([getDoc(doc(db,'seasons',season.id,'playDates',d.id,'public','lineup')),getDocs(collection(db,'seasons',season.id,'playDates',d.id,'results'))]),l=ls.exists()?ls.data():null;host.innerHTML=`<section class="hero"><h1>${esc(dateText(d.dateKey))}</h1><p>${esc(d.startTime||season?.startTime||'10:00')}–${esc(d.endTime||season?.endTime||'12:00')}</p>${l?.changedAfterPublish?'<div class="message">⚠️ Indeling gewijzigd</div>':''}</section>${!l?.published?'<div class="card"><b>Indeling is nog niet bekend.</b></div>':(l.courts||[]).map(c=>`<div class="court-card"><h3>Baan ${esc(c.number)} · ${esc(c.mode||'Dubbel')}</h3><div class="match">${esc((c.teamA||[]).join(' & '))}<br>—<br>${esc((c.teamB||[]).join(' & '))}</div></div>`).join('')}${rs.empty?'<div class="card"><h3>Uitslag</h3><p>Nog geen uitslag ingevoerd.</p></div>':`<div class="card"><h3>Uitslagen</h3>${rs.docs.map(x=>resultLine(x.data())).join('')}</div>`}${profile?.participantType==='fixed'?'<button disabled title="Deze functie wordt later geactiveerd">Uitslag invoeren – nog niet beschikbaar</button>':''}`}
async function standings(){$('screen').innerHTML='<div class="card"><h2>Stand</h2><p>Laden…</p></div>';if(!season)return;const s=await getDocs(query(collection(db,'seasons',season.id,'standings'),orderBy('points','desc'))),rows=s.docs.map((d,i)=>({rank:i+1,...d.data()}));$('screen').innerHTML='<h2>🏆 Stand</h2>'+((rows.map(r=>`<div class="standing"><span class="rank">${r.rank}</span><div><b>${esc(r.coupleName||'Koppel')}</b><br><small>${Number(r.gamesFor||0)} games voor</small></div><span class="points">${Number(r.points||0).toFixed(1).replace('.0','')} pt</span></div>`).join(''))||'<div class="card">Nog geen uitslagen verwerkt.</div>')}
function more(){$('screen').innerHTML=`<div class="tiles"><button class="tile" id="data">👤<strong>Mijn gegevens</strong><small>Contactgegevens bekijken; enkelspelvoorkeur.</small></button><button class="tile" id="rules">📘<strong>Uitleg / spelregels</strong><small>Planning, vervangers, punten en zoemer.</small></button>${admin()?'<button class="tile" id="admin">⚙️<strong>Beheer</strong><small>Seizoen, spelers, banen, uitslagen en betalingen.</small></button>':''}<button class="tile" id="logout">🚪<strong>Uitloggen</strong></button></div>`;$('rules').onclick=rules;$('admin')?.addEventListener('click',beheer);$('logout').onclick=()=>signOut(auth);$('data').onclick=data}
function data(){$('screen').innerHTML=`<div class="card"><h2>Mijn gegevens</h2><div class="formgrid"><div><label>Naam</label><div class="readonly">${esc(profile?.displayName||profile?.name||'')}</div></div><div><label>E-mailadres / inlognaam</label><div class="readonly">${esc(user?.email||'')}</div></div><div><label>Telefoon</label><div class="readonly">${esc(profile?.phone||'')}</div></div><div><label>Wil enkelspel spelen?</label><div class="readonly">${profile?.singlesAllowed===true?'Ja':'Nee'}</div></div></div><p>Contactgegevens worden door de beheerder bijgehouden. Je enkelspelvoorkeur wordt later hier zelf wijzigbaar.</p></div>`}
function rules(){$('screen').innerHTML=`<div class="card help"><h2>📘 Uitleg / begrippen / spelregels</h2><div class="help-nav"><a href="#plan">Planning</a><a href="#sub">Vervangers</a><a href="#points">Punten</a><a href="#buzzer">Zoemer</a><a href="#single">Enkelspel</a></div><h3 id="plan">Planning</h3><p>Voor iedere speelzaterdag geeft elk koppel aan wie <b>Speelt</b>, wie <b>Reserve</b> is of wie <b>Afwezig</b> is. De sluitingsdag en -tijd staan op Home en worden door de beheerder ingesteld. Na de deadline kan alleen een beheerder nog wijzigen.</p><h3 id="sub">Vervangers</h3><p>Een vervanger is pas nodig als <b>beide spelers van een koppel niet kunnen</b>. Volgorde: 1) een vaste speler van een ander koppel die die zaterdag niet speelt, 2) iemand van de reservelijst, 3) een andere vervanger. Een losse vervanger komt niet automatisch op de vaste reservelijst.</p><h3>Baanindeling</h3><p>Normaal wordt dubbel gespeeld met vier spelers per baan. Bij zes spelers kan één dubbel en één enkel worden gespeeld. Bij vier spelers één dubbel. Bij twee spelers kan alleen enkel worden gespeeld als beide spelers dat willen. Een beheerder maakt en publiceert de definitieve baanindeling.</p><h3 id="points">Punten</h3><p>De competitiepunten zijn voor het <b>koppel</b>, niet voor de individuele speler. Iedere volledig gewonnen set levert <b>1 punt</b> op. Games worden ook geregistreerd, zodat die bij een gelijke eindstand gebruikt kunnen worden.</p><h3>½ punt bij een onvoltooide laatste set</h3><p>Wordt de laatste set door het einde van de speeltijd niet afgemaakt, dan kan de partij die voorstaat <b>½ punt</b> krijgen, mits die partij in die set minimaal <b>3 games</b> heeft gewonnen. Voorbeeld: bij 3–2 bij de zoemer krijgt de leider ½ punt.</p><h3 id="buzzer">Zoemer</h3><p>Bij de zoemer wordt <b>direct gestopt</b>; een lopende rally wordt niet meer uitgespeeld. Alleen bij een exact gelijke situatie in de laatste game, bijvoorbeeld <b>5–5 en 30–30</b>, wordt na de zoemer nog <b>één beslissend punt</b> gespeeld. Bij een gelijke gamestand met een puntenvoorsprong, bijvoorbeeld <b>3–3 en 15–0</b>, gaat het halve punt naar de partij die op dat moment leidt.</p><h3>Spelen met een vervanger</h3><p>Een koppel kan met een vervanger die zaterdag maximaal <b>2 competitiepunten</b> verdienen. De gespeelde games worden wel volledig geregistreerd.</p><h3 id="single">Enkelspel</h3><p>Enkelspel mag worden gespeeld als beide spelers daarvoor beschikbaar zijn en enkelspel accepteren, maar een enkelpartij levert <b>0 competitiepunten</b> op. De uitslag kan wel voor de historie worden bewaard.</p><h3>Uitslagen en correcties</h3><p>Uitslagen worden na de speelronde ingevoerd. Zodra de invoerfunctie volledig is geactiveerd, mogen vaste deelnemers uitslagen invoeren. Een opgeslagen uitslag kan daarna alleen door een beheerder worden gecorrigeerd.</p><h3>WhatsApp</h3><p>WhatsApp-knoppen maken alleen een voorgesteld bericht klaar. De gebruiker kiest zelf de ontvanger of groep en verstuurt het bericht handmatig.</p><h3>Historie</h3><p>Bij een nieuw seizoen blijven oude speeldata, uitslagen en standen bewaard. De regels voor een eventuele finaledag, tiebreak, te laat komen of blessure zijn voor 2026/2027 nog niet als aparte competitieregels geactiveerd.</p></div>`}
function beheer(){if(!admin())return;const s=$('screen');s.innerHTML=`<div class="adminbar"><b>⚙️ Beheer</b><button class="secondary" id="close">Sluiten</button></div><div class="admintabs"><button class="active" data-a="season">Seizoen</button><button data-a="players">Spelers</button><button data-a="lineup">Indeling</button><button data-a="results">Uitslagen</button><button data-a="payments">Betalen</button>${head()?'<button data-a="admins">Beheerders</button>':''}<button data-a="rules">Uitleg</button></div><div id="ap"></div>`;$('close').onclick=()=>go('home');s.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{s.querySelectorAll('[data-a]').forEach(x=>x.classList.toggle('active',x===b));ap(b.dataset.a)});ap('season')}
function generateSaturdays(startKey,endKey){const out=[],d=keyDate(startKey),end=keyDate(endKey);while(d<=end){if(d.getDay()===6)out.push(toKey(d));d.setDate(d.getDate()+1)}return out}
async function renderSeasonAdmin(){const host=$('ap');host.innerHTML='<div class="admin-card"><h2>Seizoen & speeldata</h2><p>Laden…</p></div>';const sid=seasonId(),snap=await getDocs(query(collection(db,'seasons',sid,'playDates'),orderBy('dateKey'))),saved=snap.docs.map(d=>({id:d.id,...d.data()}));const closeDay=season?.defaultCloseDay||'friday',closeTime=season?.defaultCloseTime||'18:00';host.innerHTML=`<div class="admin-card"><div class="section-head"><div><h2>Huidig seizoen</h2><p><b>${esc(season?.name||sid)}</b><br>${esc(dateText(season?.startDate||saved[0]?.dateKey||''))} t/m ${esc(dateText(season?.endDate||saved.at(-1)?.dateKey||''))}</p></div><button id="newSeason">＋ Start nieuw seizoen</button></div><div class="season-settings"><div><label>Planning sluit op</label><select id="closeDay"><option value="wednesday" ${closeDay==='wednesday'?'selected':''}>woensdag</option><option value="thursday" ${closeDay==='thursday'?'selected':''}>donderdag</option><option value="friday" ${closeDay==='friday'?'selected':''}>vrijdag</option></select></div><div><label>Tijd</label><input id="closeTime" type="time" value="${esc(closeTime)}"></div><div><label>Standaard banen</label><input id="courts" type="number" min="1" max="8" value="${Number(season?.defaultCourts||2)}"></div></div><div class="save-explain"><b>Wanneer op Speeldata opslaan klikken?</b><br>Als je een zaterdag aan/uit zet, de sluitingsdag/-tijd wijzigt of het standaard aantal banen aanpast. Hiermee worden die instellingen voor alle getoonde speelzaterdagen opgeslagen.</div><div class="admin-actions"><button id="saveDates">Speeldata opslaan</button></div><div class="message" id="dateMsg"></div><div class="playdate-list">${saved.map(d=>`<label class="playdate-item"><input class="pd-check" type="checkbox" data-date="${esc(d.dateKey)}" ${d.status!=='cancelled'?'checked':''}><span><b>${esc(dateText(d.dateKey))}</b><br><small>${d.status!=='cancelled'?'Spelen':'Niet spelen'}</small></span><span class="count-badge">${esc(d.dateKey)}</span></label>`).join('')}</div></div><div id="newSeasonBox"></div>`;const updateCount=()=>{const n=host.querySelectorAll('.pd-check:checked').length;$('dateMsg').textContent=`${n} speelzaterdagen geselecteerd. Planning sluit ${closeDayNl($('closeDay').value)} om ${$('closeTime').value}.`;host.querySelectorAll('.playdate-item').forEach(l=>{const c=l.querySelector('input'),sm=l.querySelector('small');sm.textContent=c.checked?'Spelen':'Niet spelen';sm.className=c.checked?'':'off'})};host.querySelectorAll('.pd-check').forEach(c=>c.onchange=updateCount);$('closeDay').onchange=updateCount;$('closeTime').onchange=updateCount;updateCount();$('saveDates').onclick=savePlayDates;$('newSeason').onclick=renderNewSeasonForm}
function renderNewSeasonForm(){$('newSeasonBox').innerHTML=`<div class="admin-card"><h2>Start nieuw seizoen</h2><p>Het huidige seizoen en de historie blijven bewaard. De vaste spelers, koppels en reserves worden gekopieerd naar het nieuwe seizoen.</p><div class="formgrid"><div><label>Naam seizoen</label><input id="nsName" value="Seizoen 2027/2028"></div><div><label>Eerste zaterdag</label><input id="nsStart" type="date" value="2027-10-02"></div><div><label>Laatste zaterdag</label><input id="nsEnd" type="date" value="2028-03-25"></div><div><label>Speeltijd van</label><input id="nsStartTime" type="time" value="10:00"></div><div><label>Speeltijd tot</label><input id="nsEndTime" type="time" value="12:00"></div><div><label>Standaard banen</label><input id="nsCourts" type="number" min="1" max="8" value="2"></div><div><label>Planning sluit</label><select id="nsCloseDay"><option value="thursday">donderdag</option><option value="friday" selected>vrijdag</option></select></div><div><label>Sluitingstijd</label><input id="nsCloseTime" type="time" value="18:00"></div></div><div class="admin-actions"><button id="createSeason">Nieuw seizoen aanmaken</button></div><div id="nsMsg"></div></div>`;$('createSeason').onclick=createSeason}
async function createSeason(){const msg=$('nsMsg'),start=$('nsStart').value,end=$('nsEnd').value,name=$('nsName').value.trim();if(!start||!end||keyDate(start)>keyDate(end)){msg.textContent='Controleer de begin- en einddatum.';msg.className='message error';return}const sats=generateSaturdays(start,end);if(!sats.length){msg.textContent='Er vallen geen zaterdagen in deze periode.';msg.className='message error';return}if(!confirm(`Nieuw seizoen “${name}” starten met ${sats.length} zaterdagen?`))return;msg.textContent='Nieuw seizoen wordt aangemaakt…';msg.className='message';try{const id=`${start.slice(0,4)}-${end.slice(0,4)}`,oldId=seasonId(),[ps,cs,rs]=await Promise.all([getDocs(collection(db,'seasons',oldId,'players')),getDocs(collection(db,'seasons',oldId,'couples')),getDocs(collection(db,'seasons',oldId,'reserves'))]);let batch=writeBatch(db);batch.set(doc(db,'seasons',oldId),{active:false,updatedAt:serverTimestamp()},{merge:true});const settings={name:name||`Seizoen ${id.replace('-','/')}`,active:true,startDate:start,endDate:end,startTime:$('nsStartTime').value,endTime:$('nsEndTime').value,defaultCourts:Number($('nsCourts').value||2),defaultCloseDay:$('nsCloseDay').value,defaultCloseTime:$('nsCloseTime').value,updatedAt:serverTimestamp()};batch.set(doc(db,'seasons',id),settings,{merge:true});ps.docs.forEach(x=>batch.set(doc(db,'seasons',id,'players',x.id),{...x.data(),updatedAt:serverTimestamp()},{merge:true}));cs.docs.forEach(x=>batch.set(doc(db,'seasons',id,'couples',x.id),{...x.data(),updatedAt:serverTimestamp()},{merge:true}));rs.docs.forEach(x=>batch.set(doc(db,'seasons',id,'reserves',x.id),{...x.data(),updatedAt:serverTimestamp()},{merge:true}));sats.forEach(k=>batch.set(doc(db,'seasons',id,'playDates',k),{dateKey:k,startTime:settings.startTime,endTime:settings.endTime,courtCount:settings.defaultCourts,status:'active',closeAt:closeAtWith(k,settings.defaultCloseDay,settings.defaultCloseTime),updatedAt:serverTimestamp()}));await batch.commit();season={id,...settings};msg.textContent=`✓ ${name} aangemaakt met ${sats.length} zaterdagen. Zet eventuele vakantiezaterdagen nu uit en klik daarna op Speeldata opslaan.`;renderSeasonAdmin()}catch(e){console.error(e);msg.textContent='Nieuw seizoen aanmaken is niet gelukt.';msg.className='message error'}}
async function savePlayDates(){const b=$('saveDates'),m=$('dateMsg'),day=$('closeDay').value,time=$('closeTime').value,courts=Number($('courts').value||2);b.disabled=true;m.textContent='Bezig met opslaan…';try{const sid=seasonId(),batch=writeBatch(db);batch.set(doc(db,'seasons',sid),{defaultCloseDay:day,defaultCloseTime:time,defaultCourts:courts,updatedAt:serverTimestamp()},{merge:true});document.querySelectorAll('.pd-check').forEach(c=>{const key=c.dataset.date;batch.set(doc(db,'seasons',sid,'playDates',key),{dateKey:key,startTime:season?.startTime||'10:00',endTime:season?.endTime||'12:00',courtCount:courts,status:c.checked?'active':'cancelled',closeAt:closeAtWith(key,day,time),updatedAt:serverTimestamp()},{merge:true})});await batch.commit();season={...season,defaultCloseDay:day,defaultCloseTime:time,defaultCourts:courts};m.textContent=`✓ ${document.querySelectorAll('.pd-check:checked').length} speeldata opgeslagen. Planning sluit ${closeDayNl(day)} om ${time}.`;m.className='message'}catch(e){console.error(e);m.textContent='Opslaan lukt niet. Controleer de Firestore-regels.';m.className='message error'}finally{b.disabled=false}}
async function renderPlayersAdmin(){const host=$('ap');host.innerHTML='<div class="admin-card"><h2>Spelers & koppels</h2><p>Laden…</p></div>';const [ps,cs,rs]=await Promise.all([getDocs(collection(db,'seasons',seasonId(),'players')),getDocs(collection(db,'seasons',seasonId(),'couples')),getDocs(collection(db,'seasons',seasonId(),'reserves'))]),players=ps.docs.map(x=>({id:x.id,...x.data()})).sort((a,b)=>String(a.name).localeCompare(String(b.name),'nl'));host.innerHTML=`<div class="admin-card"><h2>Spelers & koppels</h2><div class="import-summary"><div><b>${players.length}</b>vaste spelers</div><div><b>${cs.size}</b>koppels</div><div><b>${rs.size}</b>reserves</div></div><p class="privacy-note">De eenmalige import is klaar. De gegevens staan in Firebase en hoeven niet opnieuw te worden geïmporteerd.</p><h3>Vaste spelers</h3>${players.map(p=>`<div class="person-card"><div><b>${esc(p.name||p.displayName||p.id)}</b><small>${esc(p.email||'Geen e-mail')} · ${esc(p.phone||'Geen telefoon')}</small></div><label class="mini-check"><input type="checkbox" data-single="${esc(p.id)}" ${p.singlesAllowed===true?'checked':''}> Enkelspel</label></div>`).join('')}<h3>Koppels</h3>${cs.docs.map(c=>`<div class="simple-row"><b>${esc(c.data().name||c.id)}</b></div>`).join('')}<h3>Reserves</h3>${rs.docs.map(r=>`<div class="simple-row"><span>${esc(r.data().name||r.id)}</span><small>${esc(r.data().phone||'')}</small></div>`).join('')}</div>`;host.querySelectorAll('[data-single]').forEach(ch=>ch.onchange=async()=>{try{await updateDoc(doc(db,'seasons',seasonId(),'players',ch.dataset.single),{singlesAllowed:ch.checked,updatedAt:serverTimestamp()})}catch(e){ch.checked=!ch.checked;alert('Wijzigen is niet gelukt.')}})}
let lineupState=null;
function waOpen(text){window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank')}
async function renderLineupAdmin(){const host=$('ap');host.innerHTML='<div class="admin-card"><h2>Baanindeling</h2><p>Laden…</p></div>';const ds=await playDates(),now=new Date(),sel=nextPlayDate(ds,now)||ds.at(-1);host.innerHTML=`<div class="admin-card"><h2>Baanindeling</h2><p>Kies een zaterdag, bepaal het aantal banen en controleer de spelers. Als beheerder kun je ook handmatig spelers aanwijzen om een indeling te testen.</p><label>Speeldag</label><select id="lineupDate">${ds.map(d=>`<option value="${esc(d.id)}" ${d.id===sel?.id?'selected':''}>${esc(dateText(d.dateKey))}</option>`).join('')}</select><div id="lineupBody"></div></div>`;$('lineupDate').onchange=()=>loadLineupDate(ds.find(d=>d.id===$('lineupDate').value));if(sel)loadLineupDate(sel)}
async function loadLineupDate(d){const host=$('lineupBody');host.innerHTML='<p>Laden…</p>';const [plans,ps,cps,pub]=await Promise.all([getDocs(collection(db,'seasons',seasonId(),'playDates',d.id,'couplePlans')),getDocs(collection(db,'seasons',seasonId(),'players')),getDocs(collection(db,'seasons',seasonId(),'couples')),getDoc(doc(db,'seasons',seasonId(),'playDates',d.id,'public','lineup'))]),all=ps.docs.map(x=>({id:x.id,...x.data()})).filter(x=>x.status!=='inactive').sort((a,b)=>String(a.name).localeCompare(String(b.name),'nl')),pm=new Map(all.map(x=>[x.id,x])),playing=[];plans.docs.forEach(x=>{const p=x.data();if(p.member1Status==='speelt')playing.push(pm.get(p.member1Id)||{id:p.member1Id,name:p.member1Id});if(p.member2Status==='speelt')playing.push(pm.get(p.member2Id)||{id:p.member2Id,name:p.member2Id})});const total=cps.docs.filter(x=>x.data().status!=='inactive').length,missing=Math.max(0,total-plans.size);lineupState={date:d,players:playing,allPlayers:all,selected:null,courtCount:Number(d.courtCount||season?.defaultCourts||2)};host.innerHTML=`<div class="message">${playing.length} spelers gepland · ${missing} koppels nog niet ingevuld.</div><div class="lineup-tools"><div><label>Aantal banen deze zaterdag</label><select id="dayCourts">${[0,1,2,3,4].map(n=>`<option value="${n}" ${n===lineupState.courtCount?'selected':''}>${n} ${n===1?'baan':'banen'}</option>`).join('')}</select></div><button id="saveCourts" class="secondary">Aantal banen opslaan</button></div><details class="manual-pick"><summary>Spelers handmatig aanwijzen / testen</summary><p>Vink bijvoorbeeld 8 spelers aan. Dit verandert hun gewone koppelplanning niet; het geldt alleen voor deze baanindeling.</p><div class="manual-grid">${all.map(p=>`<label><input type="checkbox" data-manual="${esc(p.id)}" ${playing.some(x=>x.id===p.id)?'checked':''}> ${esc(p.name||p.id)}</label>`).join('')}</div><button id="applyManual">Geselecteerde spelers gebruiken</button></details><div class="whatsapp-box"><h3>💬 WhatsApp uitnodiging</h3><textarea id="inviteText" rows="9"></textarea><button id="inviteWa">WhatsApp openen</button></div><div id="courtDraft"></div><div class="admin-actions"><button id="publishLineup" ${playing.length<2?'disabled':''}>✓ Indeling zichtbaar maken voor iedereen</button></div><div id="lineupMsg">${pub.exists()&&pub.data().published?'Er staat al een gepubliceerde indeling. Opnieuw publiceren markeert de indeling als gewijzigd.':''}</div><div id="lineupShare"></div>`;const refreshInvite=()=>{$('inviteText').value=`Wildenhorst zaterdagcompetitie\n\nBeste tennissers,\n\n${dateText(d.dateKey)} spelen we weer!\n\nTijd: ${d.startTime||season?.startTime||'10:00'} tot ${d.endTime||season?.endTime||'12:00'} uur.\n\nLaat via de app weten wie van jullie koppel speelt.\n\nEr hebben zich al ${lineupState.players.length} spelers aangemeld.\n${missing?`Nog ${missing} koppels moeten hun keuze doorgeven.\n`:''}\nOpen de app:\nhttps://hogeterp.github.io/Wildenhorst/`};refreshInvite();$('inviteWa').onclick=()=>waOpen($('inviteText').value);$('dayCourts').onchange=()=>{lineupState.courtCount=Number($('dayCourts').value);paintCourts()};$('saveCourts').onclick=async()=>{await updateDoc(doc(db,'seasons',seasonId(),'playDates',d.id),{courtCount:lineupState.courtCount,updatedAt:serverTimestamp()});$('lineupMsg').textContent='✓ Aantal banen voor deze zaterdag opgeslagen.';$('lineupMsg').className='message'};$('applyManual').onclick=()=>{lineupState.players=[...host.querySelectorAll('[data-manual]:checked')].map(ch=>lineupState.allPlayers.find(p=>p.id===ch.dataset.manual)).filter(Boolean);paintCourts();refreshInvite();$('publishLineup').disabled=lineupState.players.length<2};paintCourts();$('publishLineup').onclick=()=>publishLineup(pub.exists()&&pub.data().published)}
function courtModel(){const p=lineupState.players.slice(0,lineupState.courtCount*4),cs=[];for(let i=0;i<p.length&&cs.length<lineupState.courtCount;i+=4){const chunk=p.slice(i,i+4),mode=chunk.length===2?'Enkel':chunk.length>=4?'Dubbel':'Nog in te delen';cs.push({number:cs.length+1,mode,players:chunk})}while(cs.length<lineupState.courtCount)cs.push({number:cs.length+1,mode:'Nog in te delen',players:[]});return cs}
function paintCourts(){const host=$('courtDraft'),cs=courtModel();host.innerHTML=lineupState.courtCount===0?'<p><b>Deze zaterdag zijn geen banen beschikbaar.</b></p>':cs.map(c=>`<div class="court-card"><h3>Baan ${c.number} · ${esc(c.mode)}</h3><div class="slot-grid">${c.players.map(p=>`<button class="player-slot ${lineupState.selected===p.id?'picked':''}" data-pid="${esc(p.id)}">${esc(p.name||p.displayName||p.id)}${c.mode==='Enkel'?`<small>${p.singlesAllowed===true?'✓ Heeft aangegeven enkelspel te willen spelen':'⚠ Heeft enkelspel niet aangevinkt'}</small>`:''}</button>`).join('')}</div></div>`).join('');host.querySelectorAll('[data-pid]').forEach(b=>b.onclick=()=>swapPick(b.dataset.pid))}
function swapPick(id){if(!lineupState.selected){lineupState.selected=id;paintCourts();return}if(lineupState.selected===id){lineupState.selected=null;paintCourts();return}const a=lineupState.players.findIndex(p=>p.id===lineupState.selected),b=lineupState.players.findIndex(p=>p.id===id);[lineupState.players[a],lineupState.players[b]]=[lineupState.players[b],lineupState.players[a]];lineupState.selected=null;paintCourts()}
function lineupWhatsApp(courts,changed){const d=lineupState.date;let t=`Wildenhorst baanindeling\n\n${changed?'GEWIJZIGDE INDELING\n\n':''}De indeling voor ${dateText(d.dateKey)} is bekend.\n\nVeel speelplezier en een fijne tennisochtend!\n\n`;courts.forEach(c=>{t+=`Baan ${c.number}: ${c.teamA.join(' & ')} - ${c.teamB.join(' & ')}\n`});t+=`\nTijd: ${d.startTime||season?.startTime||'10:00'} tot ${d.endTime||season?.endTime||'12:00'} uur.`;return t}
async function publishLineup(changed){const m=$('lineupMsg'),courts=courtModel().filter(c=>c.players.length===2||c.players.length===4).map(c=>({number:c.number,mode:c.mode,teamA:c.mode==='Dubbel'?[c.players[0]?.name,c.players[1]?.name]:[c.players[0]?.name],teamB:c.mode==='Dubbel'?[c.players[2]?.name,c.players[3]?.name]:[c.players[1]?.name]}));try{await setDoc(doc(db,'seasons',seasonId(),'playDates',lineupState.date.id,'public','lineup'),{published:true,changedAfterPublish:!!changed,courts,publishedAt:serverTimestamp(),publishedBy:user.uid},{merge:false});m.textContent='✓ Baanindeling is zichtbaar voor iedereen.';m.className='message';const text=lineupWhatsApp(courts,changed);$('lineupShare').innerHTML=`<div class="whatsapp-box"><h3>💬 ${changed?'Gewijzigde indeling':'Baanindeling'} delen</h3><textarea id="lineupWaText" rows="10">${esc(text)}</textarea><button id="lineupWa">WhatsApp openen</button></div>`;$('lineupWa').onclick=()=>waOpen($('lineupWaText').value)}catch(e){console.error(e);m.textContent='Publiceren is niet gelukt.';m.className='message error'}}
async function renderResultsAdmin(){const host=$('ap');host.innerHTML='<div class="admin-card"><h2>Uitslagen</h2><p>Laden…</p></div>';const ds=await playDates(),now=new Date(),prev=previousPlayDate(ds,now)||ds[0],cs=await getDocs(collection(db,'seasons',seasonId(),'couples'));host.innerHTML=`<div class="admin-card"><h2>Uitslagen</h2><div class="rule-callout"><b>Puntentelling:</b> gewonnen set = 1 punt. Onvoltooide laatste set: ½ punt voor de leider als die minimaal 3 games heeft. Met vervanger maximaal 2 punten. Enkelspel = 0 competitiepunten.</div><label>Speeldag</label><select id="resultDate">${ds.map(d=>`<option value="${esc(d.id)}" ${d.id===prev?.id?'selected':''}>${esc(dateText(d.dateKey))}</option>`).join('')}</select><div class="formgrid"><div><label>Koppel A</label><select id="resA">${cs.docs.map(c=>`<option value="${esc(c.id)}">${esc(c.data().name||c.id)}</option>`).join('')}</select></div><div><label>Koppel B</label><select id="resB">${cs.docs.map(c=>`<option value="${esc(c.id)}">${esc(c.data().name||c.id)}</option>`).join('')}</select></div></div><h3>Setstanden</h3><div class="sets-entry">${[1,2,3].map(n=>`<div class="set-row"><b>Set ${n}</b><input id="s${n}a" type="number" min="0" max="99" placeholder="A"><span>–</span><input id="s${n}b" type="number" min="0" max="99" placeholder="B">${n===3?'<label class="mini-check"><input id="unfinished" type="checkbox"> Niet uitgespeeld door zoemer</label>':''}</div>`).join('')}</div><label>Opmerking</label><input id="resNote" placeholder="optioneel"><div id="pointsPreview" class="message"></div><div class="admin-actions"><button id="saveResult">Uitslag opslaan</button></div><div id="resMsg"></div><div id="resultList"></div></div>`;const calc=()=>{let pa=0,pb=0,parts=[];for(let n=1;n<=3;n++){const av=$(`s${n}a`).value,bv=$(`s${n}b`).value;if(av===''||bv==='')continue;const a=Number(av),b=Number(bv);parts.push(`${a}-${b}`);if(n===3&&$('unfinished').checked){if(a>b&&a>=3)pa+=.5;if(b>a&&b>=3)pb+=.5}else{if(a>b)pa++;if(b>a)pb++}}$('pointsPreview').textContent=`Punten: Koppel A ${pa} · Koppel B ${pb}`;return{pa,pb,scoreText:parts.join(', ')}};host.querySelectorAll('.sets-entry input').forEach(x=>x.oninput=calc);$('unfinished').onchange=calc;calc();$('resultDate').onchange=loadResultList;$('saveResult').onclick=async()=>{const a=$('resA'),b=$('resB');if(a.value===b.value){$('resMsg').textContent='Kies twee verschillende koppels.';$('resMsg').className='message error';return}const c=calc();if(!c.scoreText){$('resMsg').textContent='Vul minimaal één setstand in.';$('resMsg').className='message error';return}const id=`${Date.now()}`,data={coupleAId:a.value,coupleAName:a.options[a.selectedIndex].text,coupleBId:b.value,coupleBName:b.options[b.selectedIndex].text,scoreText:c.scoreText,pointsA:c.pa,pointsB:c.pb,unfinishedLastSet:$('unfinished').checked,note:$('resNote').value.trim(),enteredBy:user.uid,enteredAt:serverTimestamp()};try{await setDoc(doc(db,'seasons',seasonId(),'playDates',$('resultDate').value,'results',id),data);$('resMsg').textContent='✓ Uitslag opgeslagen.';$('resMsg').className='message';loadResultList()}catch(e){console.error(e);$('resMsg').textContent='Opslaan lukt niet. Controleer de Firestore-regels.';$('resMsg').className='message error'}};loadResultList()}
async function loadResultList(){const host=$('resultList'),id=$('resultDate')?.value;if(!host||!id)return;const rs=await getDocs(collection(db,'seasons',seasonId(),'playDates',id,'results'));host.innerHTML=`<h3>Opgeslagen</h3>${rs.empty?'<p>Nog geen uitslagen.</p>':rs.docs.map(x=>`<div class="result-admin"><div>${resultLine(x.data())}${x.data().note?`<small>${esc(x.data().note)}</small>`:''}</div><button class="danger" data-delres="${esc(x.id)}">Verwijder</button></div>`).join('')}`;host.querySelectorAll('[data-delres]').forEach(b=>b.onclick=async()=>{if(!confirm('Deze uitslag verwijderen?'))return;await deleteDoc(doc(db,'seasons',seasonId(),'playDates',id,'results',b.dataset.delres));loadResultList()})}
async function renderPaymentsAdmin(){const host=$('ap');host.innerHTML='<div class="admin-card"><h2>Betalingen</h2><p>Laden…</p></div>';const [ps,pays]=await Promise.all([getDocs(collection(db,'seasons',seasonId(),'players')),getDocs(collection(db,'seasons',seasonId(),'payments'))]),players=ps.docs.filter(x=>x.data().status!=='inactive').map(x=>({id:x.id,...x.data()}));host.innerHTML=`<div class="admin-card"><h2>Betalingen</h2><p>Alleen vaste spelers betalen. Reserves tellen niet mee.</p><div class="formgrid"><div><label>Naam betaling</label><input id="payName" placeholder="bijv. Wintertennis termijn 1"></div><div><label>Totaal bedrag (€)</label><input id="payTotal" type="number" min="0" step="0.01"></div></div><div class="admin-actions"><button id="newPayment">Betaling aanmaken</button></div><div id="payMsg"></div><div id="payList"></div></div>`;$('newPayment').onclick=async()=>{const total=Number($('payTotal').value),name=$('payName').value.trim();if(!name||!total){$('payMsg').textContent='Vul een naam en totaalbedrag in.';$('payMsg').className='message error';return}const entries={};players.forEach(p=>entries[p.id]={name:p.name||p.id,paid:false,paidAt:null,note:''});await setDoc(doc(db,'seasons',seasonId(),'payments',`p_${Date.now()}`),{name,totalAmount:total,perPlayer:Number((total/players.length).toFixed(2)),playerCount:players.length,entries,createdAt:serverTimestamp()});$('payName').value='';$('payTotal').value='';$('payMsg').textContent=`✓ Betaling aangemaakt: € ${(total/players.length).toFixed(2)} per speler.`;$('payMsg').className='message';renderPaymentsAdmin()};renderPaymentList(pays,players)}
function renderPaymentList(pays,players){const host=$('payList');if(!host)return;host.innerHTML=pays.empty?'<p>Nog geen betalingen aangemaakt.</p>':pays.docs.map(p=>{const d=p.data(),entries=d.entries||{},paid=Object.values(entries).filter(x=>x.paid).length,count=d.playerCount||players.length,paidAmount=paid*Number(d.perPlayer||0),open=Math.max(0,Number(d.totalAmount||0)-paidAmount),unpaid=players.filter(x=>!(entries[x.id]||{}).paid);return `<div class="payment-card"><div class="date-head"><h3>${esc(d.name||'Betaling')}</h3><span class="status">${paid}/${count} betaald</span></div><div class="payment-summary"><b>${paid} van ${count} betaald</b><span>Betaald: € ${paidAmount.toFixed(2)}</span><span>Openstaand: € ${open.toFixed(2)}</span><span>Nog te betalen: ${unpaid.length} spelers</span></div><progress max="${count}" value="${paid}"></progress><p>Totaal € ${Number(d.totalAmount||0).toFixed(2)} · € ${Number(d.perPlayer||0).toFixed(2)} per speler</p><button class="wa-remind" data-remind="${esc(p.id)}">💬 WhatsApp herinnering openstaande betalingen</button>${players.map(x=>{const e=entries[x.id]||{name:x.name,paid:false};return `<div class="pay-row"><span>${esc(e.name||x.name)}</span><button data-pay="${esc(p.id)}" data-player="${esc(x.id)}" class="${e.paid?'paid':'secondary'}">${e.paid?'✓ Betaald':'Openstaand'}</button></div>`}).join('')}</div>`}).join('');host.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>togglePayment(b.dataset.pay,b.dataset.player));host.querySelectorAll('[data-remind]').forEach(b=>b.onclick=()=>{const pd=pays.docs.find(x=>x.id===b.dataset.remind)?.data();if(!pd)return;const unpaid=players.filter(x=>!(pd.entries?.[x.id]||{}).paid),names=unpaid.map(x=>x.name||x.id).join(', ');waOpen(`Wildenhorst zaterdagcompetitie\n\nBeste tennissers,\n\nEen kleine herinnering voor ${pd.name||'de betaling'}.\nVolgens mijn overzicht staat € ${Number(pd.perPlayer||0).toFixed(2)} nog open voor:\n${names}\n\nAlvast bedankt!`)})}
async function togglePayment(paymentId,playerId){const ref=doc(db,'seasons',seasonId(),'payments',paymentId),s=await getDoc(ref);if(!s.exists())return;const d=s.data(),entries={...(d.entries||{})},e={...(entries[playerId]||{})};e.paid=!e.paid;e.paidAt=e.paid?new Date().toISOString():null;entries[playerId]=e;await updateDoc(ref,{entries,updatedAt:serverTimestamp()});renderPaymentsAdmin()}
async function renderAdminsAdmin(){const host=$('ap');host.innerHTML='<div class="admin-card"><h2>Beheerders</h2><p>Laden…</p></div>';const us=await getDocs(collection(db,'users'));host.innerHTML=`<div class="admin-card"><h2>Beheerders</h2><p>Alleen de hoofdbeheerder kan beheerdersrechten geven of intrekken. Alleen spelers die al een account hebben geactiveerd verschijnen hier.</p>${us.docs.map(x=>{const d=x.data(),isHead=d.role==='headAdmin',isAdmin=d.role==='admin';return `<div class="person-card"><div><b>${esc(d.name||d.displayName||d.email||x.id)}</b><small>${esc(d.email||'')} · ${isHead?'Hoofdbeheerder':isAdmin?'Beheerder':'Speler'}</small></div>${isHead?'<span class="status green">Hoofdbeheerder</span>':`<button data-roleuid="${esc(x.id)}" data-isadmin="${isAdmin?'1':'0'}">${isAdmin?'Rechten intrekken':'Maak beheerder'}</button>`}</div>`}).join('')}<div id="adminMsg"></div></div>`;host.querySelectorAll('[data-roleuid]').forEach(b=>b.onclick=async()=>{try{await updateDoc(doc(db,'users',b.dataset.roleuid),{role:b.dataset.isadmin==='1'?'player':'admin'});renderAdminsAdmin()}catch(e){console.error(e);$('adminMsg').textContent='Wijzigen lukt niet. Controleer de Firestore-regels.';$('adminMsg').className='message error'}})}
function renderAdminHelp(){const host=$('ap');host.innerHTML=`<div class="admin-card help"><h2>📚 Handboek voor de beheerder</h2><div class="help-nav"><a href="#a-season">Seizoen</a><a href="#a-plan">Planning</a><a href="#a-lineup">Indeling</a><a href="#a-results">Uitslagen</a><a href="#a-pay">Betalen</a><a href="#a-admin">Beheerders</a></div><h3 id="a-season">Nieuw seizoen</h3><p>Gebruik <b>Start nieuw seizoen</b> in Beheer → Seizoen. Vul begin- en einddatum, speeltijd, standaard aantal banen en de sluitingsdag/-tijd in. De app maakt automatisch alle zaterdagen aan en kopieert vaste spelers, koppels en reserves. Zet daarna vakantiezaterdagen uit en sla de speeldata op. Oude seizoenen blijven bewaard.</p><h3>Speeldata opslaan</h3><p>Gebruik deze knop nadat je speelzaterdagen aan/uit zet, de deadline wijzigt of het aantal banen aanpast. De deadline wordt per zaterdag in Firebase vastgelegd.</p><h3 id="a-plan">Planning</h3><p>Normaal speelt één speler per koppel en staat de partner reserve. Spelers kunnen wijzigen tot de ingestelde deadline. Na de deadline kan alleen een beheerder nog aanpassen. Bij twee afwezige spelers is een vervanger nodig.</p><h3>Vervangers</h3><p>Prioriteit: niet-spelende vaste speler → reserve → andere vervanger. Een handmatige vervanger wordt niet automatisch aan de reservelijst toegevoegd. Met een vervanger kan een koppel maximaal 2 competitiepunten halen.</p><h3 id="a-lineup">Baanindeling</h3><p>Beheer → Indeling haalt automatisch de spelers op die op <b>Speelt</b> staan. Tik twee namen aan om ze te wisselen. Publiceren maakt de indeling zichtbaar bij Zaterdag. Bij een wijziging na publicatie verschijnt een waarschuwing.</p><h3>Enkelspel</h3><p>Controleer de enkelspelvoorkeur van spelers. Enkelspel levert 0 competitiepunten op. Bij 6 spelers is één dubbel plus één enkel mogelijk; bij 4 spelers één dubbel.</p><h3 id="a-results">Uitslagen en punten</h3><p>Gewonnen set = 1 punt. Laatste onvoltooide set: ½ punt voor de leider als die minimaal 3 games heeft. Bij de zoemer direct stoppen; alleen bij exact gelijke game-/puntenstand (zoals 5–5, 30–30) nog één beslissend punt. Games altijd registreren. Een beheerder kan opgeslagen uitslagen corrigeren.</p><h3>Stand</h3><p>De stand is per koppel. Individuele spelers krijgen geen eigen competitiepunten. Games blijven bewaard voor eventuele gelijke eindstanden.</p><h3 id="a-pay">Betalingen</h3><p>Maak per termijn of betaling een apart onderdeel aan en voer het totale bedrag in. De app deelt dat bedrag gelijk over alle actieve vaste spelers. Reserves betalen niet. Markeer per speler betaald/openstaand.</p><h3 id="a-admin">Beheerders</h3><p>De hoofdbeheerder kan een geactiveerd spelersaccount beheerder maken of de rechten intrekken. Een beheerder kan operationele zaken beheren, maar kan geen hoofdbeheerder wijzigen.</p><h3>WhatsApp</h3><p>De app verstuurt nooit automatisch WhatsApp-berichten. Een knop maakt alleen een conceptbericht klaar; de gebruiker kiest zelf de ontvanger en drukt zelf op verzenden.</p><h3>Privacy en techniek</h3><p>Persoonsgegevens staan in Firebase, niet in de openbare GitHub-code. Wachtwoorden worden door Firebase Authentication afgehandeld. Technische Firebase-teksten horen niet in spelersschermen.</p></div>`}
function ap(t){if(t==='season')return renderSeasonAdmin();if(t==='players')return renderPlayersAdmin();if(t==='lineup')return renderLineupAdmin();if(t==='results')return renderResultsAdmin();if(t==='payments')return renderPaymentsAdmin();if(t==='admins')return renderAdminsAdmin();if(t==='rules')return renderAdminHelp()}
